import{_ as t,o,c as a,a3 as r}from"./chunks/framework.cNy3aYYk.js";const p=JSON.parse('{"title":"Calendar Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Calendar Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/calendar-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Calendar Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/calendar-overview"}]]},"headers":[],"relativePath":"user-guide/calendar-overview.md","filePath":"user-guide/calendar-overview.md","lastUpdated":1791561813000}'),n={name:"user-guide/calendar-overview.md"};function i(l,e,d,s,c,g){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="calendar-module" tabindex="-1">Calendar Module <a class="header-anchor" href="#calendar-module" aria-label="Permalink to &quot;Calendar Module&quot;">​</a></h1><p>Personal calendar events for tenant workspaces. Week/Day time grids, Month, and Agenda views with org-wide visibility for owners/admins. <a href="/user-guide/meetings-overview">Meetings</a> (book + assign host + Zoom/Meet) project onto Calendar for the host and for internal invitees (view-only).</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/calendar">calendar.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/calendar">calendar.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/calendar">calendar.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-calendar">tenant-v1-calendar.md</a></td></tr></tbody></table><h2 id="capabilities-v1" tabindex="-1">Capabilities (v1) <a class="header-anchor" href="#capabilities-v1" aria-label="Permalink to &quot;Capabilities (v1)&quot;">​</a></h2><ul><li>Personal events (<code>organizer_id</code> = creator)</li><li><strong>Week</strong> (default) + <strong>Day</strong> views with vertical hourly time slots (Google Calendar–style)</li><li>Side-by-side layout for overlapping events</li><li>Drag-and-drop reschedule on Week/Day (<code>calendar.update</code>)</li><li>Month + Agenda views</li><li>Create / update / cancel / delete</li><li>Workspace timezone-aware display and editing</li><li><code>calendar.view_all</code> for workspace Owner / Admin / Manager oversight</li><li>Upcoming events dashboard widget</li><li><strong>Overlays</strong> — <a href="/user-guide/meetings-overview">Meetings</a> (host + internal invitees, view-only for invitees), <a href="/user-guide/projects-overview">Projects</a> (start/end all-day), <a href="/user-guide/tasks-overview">Tasks</a> (due datetime), and <a href="/user-guide/leads-overview">Leads</a> (next follow-up) project sourced events (<code>source</code> = <code>meeting</code>|<code>project</code>|<code>task</code>|<code>lead</code>)</li><li>Module licensing (<code>module:calendar</code>) + Spatie permissions — catalog <strong>1.6.0</strong></li><li><strong>Event shares (1.3.0)</strong> — share a manual event with workspace users as <strong>viewer</strong> (read-only) or <strong>editor</strong> (can edit/delete with Spatie permissions)</li><li><strong>Google / Outlook sync (1.4.0–1.6.0)</strong> — push manual + Meeting/Task/Lead overlays; pull provider events as read-only External events (<strong>1.6.0</strong>). See &quot;Google / Outlook sync&quot; below.</li><li>Meeting invitee list/view ACL for projected meetings (<strong>1.2.0</strong>)</li><li>Activity logging (<code>LogsActivity</code>)</li><li>API <code>read_only</code> flag for invitee / sharee / non-organizer viewers</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>calendar.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>view_all</code> · <code>manage_integrations</code></p><h2 id="google-outlook-sync" tabindex="-1">Google / Outlook sync <a class="header-anchor" href="#google-outlook-sync" aria-label="Permalink to &quot;Google / Outlook sync&quot;">​</a></h2><ul><li>Personal, per-user connect — Settings live at <strong>Calendar → Sync</strong> (requires <code>calendar.manage_integrations</code>, granted to the admin role by default).</li><li><strong>Push (EloSync → provider):</strong> manual events + Meeting / Task / Lead overlays (<strong>1.5.0</strong>).</li><li><strong>Pull (provider → EloSync):</strong> provider events appear as read-only <strong>External</strong> events (<strong>1.6.0</strong>). Use <strong>Sync now</strong> or wait for the hourly pull. EloSync-owned events are not overwritten from the provider.</li><li><strong>Not pushed:</strong> Project / Contact / Company overlays (still deferred).</li><li>Requires the platform operator to configure a Google and/or Microsoft OAuth app (see <a href="/deployment/calendar">deployment</a>); if not configured, the Connect button is disabled with a &quot;not configured on this platform&quot; badge.</li><li>Disconnecting stops future push/pull; it does not delete events already created on the provider&#39;s calendar.</li></ul><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Calendar assignment / assignee / create-on-behalf</li><li>Named team calendars / department auto-share</li><li>Webhook / push-notification driven inbound (polling only in <strong>1.6.0</strong>)</li><li>Pushing Project / Contact / Company overlay events to providers</li><li>Customer Portal visibility into calendar sync</li></ul><p>Meetings, Zoom, and Google Meet are documented under <a href="/user-guide/meetings-overview">Meetings</a>.</p>',13)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
